# %% [markdown]
# # Paper figures — reproducible orchestrator
#
# Runs every figure in the paper, in order, from the current state of
# `data/derived/`. Each figure's generating code lives in its own script in
# `paper/`; this notebook is the single entry point so that one command
# regenerates every image shipped with the manuscript.
#
# Prerequisites (all should already be regenerated by the earlier
# notebooks and scripts; this notebook does NOT re-run them):
#   - `data/derived/oh_decomposition_all_drugs.csv`   (notebook/05)
#   - `data/derived/feng_decomposition.csv`           (notebook/04)
#   - `data/derived/topk_recovery.csv`                (scripts/recompute_topk_with_ci.py)
#   - `data/derived/benchmark_r3.csv`                 (scripts/recompute_benchmark_r3.py)
#   - `data/derived/retrospective_validation.csv`    (notebook/06)
#   - `data/derived/paper_numbers.json`               (scripts/compute_paper_numbers.py)
#
# Figures produced (both PNG at 300 dpi and PDF, written to `paper/`):
#   - Figure 1 — supply × selection schematic + atlas coverage overview
#   - Figure 2 — mutagen substitution spectra + class coverage score
#   - Figure 3 — chemistry blind-spots matrix + top-K recovery with Wilson CI bands
#   - Figure 4 — three-panel retrospective validation
#
# Each `paper/figure_N.py` is self-contained and loads the derived data it
# needs. This notebook just runs them in a controlled Python namespace so
# matplotlib state does not bleed between figures.

# %%
from __future__ import annotations

import runpy
import sys
from pathlib import Path

import matplotlib.pyplot as plt

NOTEBOOK_DIR = Path(__file__).resolve().parent
PROJECT_ROOT = NOTEBOOK_DIR.parent
sys.path.insert(0, str(PROJECT_ROOT))

PAPER_DIR = PROJECT_ROOT / "paper"

FIGURES = [
    ("Figure 1 — supply × selection schematic + atlas coverage",
     PAPER_DIR / "figure_1.py"),
    ("Figure 2 — mutagen substitution spectra + class coverage",
     PAPER_DIR / "figure_2.py"),
    ("Figure 3 — chemistry blind-spots + top-K recovery (Wilson 95% CI bands)",
     PAPER_DIR / "figure_3.py"),
    ("Figure 4 — three-panel retrospective validation (Doi / Takei / Nuvalent)",
     PAPER_DIR / "figure_4.py"),
]


def run_figure(title: str, script: Path) -> None:
    """Run one figure script in a fresh namespace, then close its figures."""
    print()
    print("=" * 72)
    print(f"  {title}")
    print(f"  {script.relative_to(PROJECT_ROOT)}")
    print("=" * 72)
    if not script.exists():
        print(f"  [SKIP] {script} not found")
        return
    runpy.run_path(str(script), run_name="__paper_figure__")
    plt.close("all")  # free memory + guarantee no stale state leaks


# %%
for title, script in FIGURES:
    run_figure(title, script)

print()
print("=" * 72)
print(f"  All figures written to {PAPER_DIR.relative_to(PROJECT_ROOT)}/")
for _, s in FIGURES:
    for ext in (".pdf", ".png"):
        out = PAPER_DIR / (s.stem + ext)
        if out.exists():
            size_kb = out.stat().st_size / 1024
            print(f"    {out.relative_to(PROJECT_ROOT)}   ({size_kb:,.0f} KB)")
print("=" * 72)
